changeSet.sql:
CREATE INDEX media_file_ix_track_match_gps_time
    ON media_file (exif_gps_date)
    WHERE exif_gps_date IS NOT NULL;

CREATE INDEX media_file_ix_track_match_local_time
    ON media_file (exif_date_image_taken)
    WHERE exif_gps_date IS NULL AND exif_date_image_taken IS NOT NULL;

CREATE INDEX gps_track_data_points_ix_media_time_match
    ON gps_track_data_points (gps_track_data_id, point_timestamp, point_index)
    WHERE point_timestamp IS NOT NULL;
